#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const root = path.resolve(__dirname, '..');
const debugLog = path.join(root, 'firestore-debug.log');
const firebaseBin = path.join(root, 'node_modules', '.bin', 'firebase');
const budgetPattern = /maximum of 1000 expressions to evaluate has been reached/gi;

// This file is generated by the emulator. Clear only this disposable log so a
// previous run cannot make the current ruleset look worse or better than it is.
fs.writeFileSync(debugLog, '', 'utf8');

const result = spawnSync(firebaseBin, [
  'emulators:exec',
  '--only', 'firestore',
  '--project', 'demo-editflow',
  'node tests/firestore-rules.test.cjs',
], {
  cwd: root,
  env: process.env,
  stdio: 'inherit',
});

if (result.error) {
  console.error(result.error);
  process.exit(1);
}
if (result.status !== 0) process.exit(result.status || 1);

const log = fs.readFileSync(debugLog, 'utf8');
const budgetErrors = log.match(budgetPattern) || [];
if (budgetErrors.length > 0) {
  console.error(`FAILED: Firestore Rules hit the 1,000-expression limit ${budgetErrors.length} time(s).`);
  process.exit(1);
}

console.log('PASS: Firestore emulator log contains 0 expression-limit errors');
